) AS (
  VALUES 
    (822::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-09T00:00:00+00:00'::TIMESTAMPTZ, '78f5102ddfed4b670cfc0fab942f953364c6d7eeba3e26a7427cb3786187146e'::TEXT, ARRAY[568]::BIGINT[]),
    (822::BIGINT, 'Muy buen profesor. Siempre atento a las consultas dentro clase. Da una breve explicación del experimento y del informe después de hacer el quiz al empezar la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '2c94178d7dba6374f3a20fa8959e63a7d9184e454048bf6da00b2f0ad444e354'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Excelente a la hora de explicar las cosas de manera súper clara. Es muy comprensivo con los estudiantes y no califica tan duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, '6e2fdfcd55cafe17fba8f26edc864891558bc069a63029a75e488b0e56c3990b'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (822::BIGINT, 'El profe es una amor, te ayuda mucho en las calificaciones pero si califica medio duro, pero al final como que se arrepiente y te ayuda, si tienes dudas hasta para otro curso relacionado con Química te ayudará, super recomendado que matricule hasta para otro curso, muy excelente profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c5473d9eeaad6fb6f0d1fd3247b02786f4d0798cfeed3870ed917a5b659df116'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Muy buen profe, es divertido y muy comprensivo con las ausencias, califica informes y exámenes suave. Los quices son muy fáciles, si pueden metan con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '171b37b1c7fef4bfe96b9d4d6f3a5addb8f3b25ee3451edc64b76915c7fc0735'::TEXT, ARRAY[613]::BIGINT[]),
    (822::BIGINT, 'El profe es súper buena persona. Siempre dispuesto a atender dudas dentro y fuera de la clase. Comprensivo y califica justo. Intenta que tengamos el mayor interés posible en clase. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a9eb3fe64b3ccc0ae0e0e658080128b76e2ee59d27428e8693028c5a1b9aed94'::TEXT, ARRAY[613]::BIGINT[]),
    (822::BIGINT, 'El profe es demasiado bueno, comprensivo y si uno tiene dudas el le ayuda a uno de manera amable. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '5c2f0a3324086d00b6dc2a6f22fd6166495adeb9b7a565681d4c21b7849fba6a'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Muy buen profe, explica todo súper calro y es muy comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c92c633af90c6f029fab8dabb50922c7e937b6f433e67e19a4e9c8b8cdb31ca0'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Si pueden lleven con él, explica bien y el curso se hace relativamente relajado, responde a los correos rápido, si uno no sabe algo se lo explica amablemente, para los quiz les recomiendo estudiar algo (no son rudos pero si no repasó le va malillo). No califica duro los informes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'fc8e0f77a15d546fe1d5fb1cb727e5df21911b973543d073873db02afe239529'::TEXT, ARRAY[567]::BIGINT[]),
    (822::BIGINT, 'No califica duro para nada, los exámenes previos son fáciles si estudia antes. El problema es la cátedra como hacía los exámenes, metían cosas que no se veían claramente en clases. Pero el profe ayuda en las prácticas, es amable y transmite confianza. No le reclame puntos por favor, es muy justo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2022-12-13T00:00:00+00:00'::TIMESTAMPTZ, '6c980ff5e0608d8d0e82529a2439d1d31e0b88885121727e147ea00cdcba7038'::TEXT, ARRAY[613]::BIGINT[]),
    (822::BIGINT, 'Entra en el top 3 de los mejores profes de la cátedra de química, me soprende como tiene tan pocas calificaciones. Es un crack, tiene demasiados estudios y es una excelente persona. Matricularía mil veces con él'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a7aa7c06e804420026f2ad71c834b6e94eacfa146c32f410112bdeed86918022'::TEXT, ARRAY[568]::BIGINT[]),
    (822::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-03T00:00:00+00:00'::TIMESTAMPTZ, '6fcc9697109efbfbed529c10fca04774aee55a884bef44795131cd9325953a0d'::TEXT, ARRAY[613]::BIGINT[]),
    (822::BIGINT, 'El mae es un crack de profe. No lo complica a uno con demasiadas varas que sobran como hacer el 100% de la libreta a mano. Explica demasiado bien, tiene muy buena actitud siempre y ayuda con lo que uno necesite. Seriamente si puede meter este lab con él, hágalo, no se va a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-18T00:00:00+00:00'::TIMESTAMPTZ, '8d1c73380d6ea7238e9ffd3eb1d8a1e015dc7989dceb3599c28f6c502dbd6e24'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'El profe explica muy bien. Hubo bastantes trabajos y avisa con una semana de anticipación cada quiz (en total hicimos 6). Pero el profe es demasiado pura vida, tiene mucha paciencia y repite lo que sea necesario si las personas no entienden'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'd01e1ba514cb2be1950061487b651647c63e01350e0b4e935e287e63880e7226'::TEXT, ARRAY[568]::BIGINT[]),
    (822::BIGINT, 'No dude en matricular con él, definitivamente es un excelente profesor, la asistencia no es obligatoria y graba las clases, hace bastante práctica para preparse bien para el examen y resuelve cualquier duda. Excelente persona también'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6d788fa932472d59ebaa460b71e5ef6dfa924204addf4680ad7155e918b6221e'::TEXT, ARRAY[568]::BIGINT[]),
    (822::BIGINT, 'No requiere mucha participación. Explica muy claramente. Responde las consultas muy rápido, y se nota que tiene vocación. Súper recomendado-'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6eebbd494eae071bcb9560d3dd13190e617b0c9eb3af444589787abc4c86f09d'::TEXT, ARRAY[568]::BIGINT[]),
    (822::BIGINT, 'Es lo mejor, matricularía con él siempre.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'e503a06d932463b16a0c743ae859c5eaf0afb8d2fc82398b648aa05181490784'::TEXT, ARRAY[568]::BIGINT[]),
    (822::BIGINT, 'Es muy buen profe, responde rápido las dudas, las clases son cortas pero concisas, los quices son fáciles, es solo de repasar el material que utiliza en las clases y la teoría de las prácticas, califica de manera justa, es solo tomarse el tiempo de hacer los informes y tener cuidado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-01-01T00:00:00+00:00'::TIMESTAMPTZ, '425cdfa4c22243705d84cd0adad1a48f68c4a5ee65088280d2b1f7955223a927'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Este profe es muy bueno , es súper entendible , hace los quiz muy cortos y fáciles , los ensayos los califica justos , al final escoje los mejores para tu nota así no te perjudica tanto ! Es muy amable y sus clases son de mucho 30 minutos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '7b27ceb073e472b92a67dc470527f9d581dbf5b57e7891fd47a3f2256f0ae88d'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'El curso se pasa muy fácil con él. Las clases sincrónicas son super cortas. Sus explicaciones son claras. Hace quices un poco confusos pero todo bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '4b4a0141df5955b3fa33f270ee926ba37abb7d60b125cd55a772998952b52e83'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Super bueno para virtual. La clase es corta pero explica muy bien todo. Siempre contesta dudas, no importa que no sea en consulta'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'ade8d89a6f28dd7dccbbb331e43a5f7d629759fd03bd710ad3fff9a1e1dc85f6'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Clases rápidas pero concisas, lo mejor que vas a encontrar para llevar Lab.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '015f5c77ed7e681fbef0a1736a4183f0fac18f9eb77efe1b463ec3dde3b957a5'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (822::BIGINT, 'Es un excelente profesor, las clases son muy cortas y claras. El curso es bastante sencillo en la virtualidad si se lleva con él. Está dispuesto a ayudarle al estudiante en cualquier momento. Sea puntual y le va a ir bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '898e7b83eb9b06d32e2f070e77a0159958e4e3d23cdcf6085626fe14af0dc075'::TEXT, ARRAY[567]::BIGINT[]),
    (822::BIGINT, 'Excelente profesor. Siempre atento a las necesidades de los estudiantes y a las dudas. Toda la materia siempre quedó muy clara y matricular con él es pasar de fijo. Se debe poner buen tiempo en hacer los reportes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4ca8fad5146fa7aaa859ec75ea3aeca59a18a18bf18ea6f210bcccf4b5741172'::TEXT, ARRAY[567]::BIGINT[]),
    (822::BIGINT, 'Las clases son cortas pero concisas, deja todo claro, califica suave, aclara dudas, puede ser flexible con las entregas, se preocupa por que uno entienda , por su nota y que haya un equilibrio con teoría. Calidad de profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f4c7b95c67e3616ff7b0893e074b46a370f8be8ec05d43dba810be8b9017531e'::TEXT, ARRAY[613]::BIGINT[]),
    (822::BIGINT, 'Explica muy claro y siempre resuelve las dudas de los estudiantes. Califica suave.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '64c2dd720f01693c9b7b481fd914cab38a85832b3721e820a5df13ece4113d8d'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'No lo dude, lleve el curso con él. Explica bien, genera un ambiente de confianza y respeto, ayuda al grupo en general con quices extra, está pendiente de el ritmo de teoría y se adapta a este. Si tiene dudas y le escribe, siempre contesta y ayuda. Al menos virtual 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '838bcc9d5506418930c20ac4b64e2a2736004f0b9d6f88ccb8521afbb1b95b88'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Sinceramente si uno hace los trabajos lo mejor posible, le va a ir bien. Se preocupa que el estudiante entienda y si tiene dudas, él ayuda en lo que puede. En virtualidad fue una clase corta pero clara. Por supuesto, debe llevar la materia de teoría al día para no perderse.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'c42853ac83a8b05af74d4e608dc2c301354462d360f73731ca681123c6f08e18'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Es un excelente profe, muy buena gente y hace lo posible para que a todos les vaya bien en el curso. Explica muy claro y siempre está súper atento a dudas ya sea durante clase o en hora de consulta. Si puede meter con él no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, '20baac73db457c69ccbc6be5860d5a8a2e1a0f07ba5d9d0ec33f4bfc90ef3f71'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '157232d1b7f02affcffb5c19711d53485262c9e71097f40096e9fbc6539108d3'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Excelente profesor. Es muy pura vida. Explica bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'c9fc66256eac0e74d7d4a5a56afd63a61a8e0c68eac76318526e6845b49c1b51'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (822::BIGINT, 'Siempre da consulta y explica muy bien!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'bd5f76655852fbc28625518470fefc85a81bb219be405f92565edd8f766f1d78'::TEXT, ARRAY[568]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
